<script setup>
import { Head, useForm, usePage } from '@inertiajs/vue3';
import HrmsLayout from '@/Layouts/HrmsLayout.vue';
const props = defineProps({ users:Array, roles:Array, workflows:Array, leaveTypes:Array, employees:Array, entitlements:Array });
const page = usePage();
const roleForm = useForm({role_id:''});
const entitlement = useForm({employee_id:'',leave_type_id:props.leaveTypes[0]?.id || '',year:new Date().getFullYear(),allocated_days:21,carried_days:0});
const workflow = useForm({name:'',department_id:'',leave_type_id:'',requester_role_id:'',priority:100,effective_from:new Date().toISOString().slice(0,10),steps:[{approver_role_id:'',approver_scope:'department_manager'}]});
const component = useForm({code:'',label:'',kind:'allowance',amount:'',effective_from:new Date().toISOString().slice(0,10)});
const componentEmployee = useForm({employee_id:''});
const assign = (user, event) => useForm({role_id:Number(event.target.value)}).post(route('settings.role',user.id));
const saveEntitlement = () => entitlement.post(route('settings.entitlement'),{onSuccess:()=>entitlement.reset('employee_id')});
const saveWorkflow = () => workflow.post(route('settings.workflow'),{onSuccess:()=>workflow.reset('name')});
const saveComponent = () => component.post(route('settings.component',componentEmployee.employee_id),{onSuccess:()=>component.reset('code','label','amount')});
</script>
<template><Head title="الإعدادات" /><HrmsLayout title="إعدادات النظام" subtitle="أدوار الوصول ومسارات الموافقة وأرصدة الإجازة وبنود الرواتب.">
    <div class="grid gap-6 xl:grid-cols-2">
        <section class="panel p-5"><h2 class="text-lg font-bold text-[#1F3A5F]">المستخدمون والأدوار</h2><div class="mt-4 space-y-3"><div v-for="user in users" :key="user.id" class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 pb-3 last:border-0"><div><div class="font-semibold">{{ user.name }}</div><div class="text-xs text-slate-500">{{ user.email }}</div></div><select :value="user.roles?.[0]?.id" :disabled="!page.props.auth.roles.includes('super_admin')" class="field w-44" :aria-label="`دور ${user.name}`" @change="assign(user,$event)"><option v-for="role in roles" :key="role.id" :value="role.id">{{ role.name }}</option></select></div></div></section>
        <section class="panel p-5"><h2 class="text-lg font-bold text-[#1F3A5F]">رصيد الإجازة</h2><form class="mt-4 grid gap-3 sm:grid-cols-2" @submit.prevent="saveEntitlement"><div><label class="label" for="ent_employee">الموظف</label><select id="ent_employee" v-model="entitlement.employee_id" class="field" required><option value="">اختر موظفًا</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.first_name }} {{ e.last_name }}</option></select></div><div><label class="label" for="ent_type">نوع الإجازة</label><select id="ent_type" v-model="entitlement.leave_type_id" class="field"><option v-for="t in leaveTypes" :key="t.id" :value="t.id">{{ t.name }}</option></select></div><div><label class="label" for="ent_year">السنة</label><input id="ent_year" v-model.number="entitlement.year" type="number" class="field"></div><div><label class="label" for="ent_days">الأيام المخصصة</label><input id="ent_days" v-model.number="entitlement.allocated_days" type="number" min="0" class="field"></div><div><label class="label" for="ent_carried">المرحل</label><input id="ent_carried" v-model.number="entitlement.carried_days" type="number" min="0" class="field"></div><div class="flex items-end"><button class="btn-primary w-full" :disabled="entitlement.processing">حفظ الرصيد</button></div><p v-if="Object.keys(entitlement.errors).length" class="error sm:col-span-2">{{ Object.values(entitlement.errors)[0] }}</p></form><p class="mt-4 text-xs text-slate-500">{{ entitlements.length }} سجل رصيد للسنة الحالية.</p></section>
        <section class="panel p-5"><h2 class="text-lg font-bold text-[#1F3A5F]">مسار موافقة جديد</h2><p class="mt-1 text-sm text-slate-500">أضف خطوات حسب ترتيب اعتماد الطلب.</p><form class="mt-4 space-y-3" @submit.prevent="saveWorkflow"><div><label class="label" for="workflow_name">اسم المسار</label><input id="workflow_name" v-model.trim="workflow.name" class="field" required></div><div class="grid gap-3 sm:grid-cols-2"><div><label class="label" for="requester_role">دور مقدم الطلب</label><select id="requester_role" v-model="workflow.requester_role_id" class="field"><option value="">كل الأدوار</option><option v-for="role in roles" :key="role.id" :value="role.id">{{ role.name }}</option></select></div><div><label class="label" for="leave_type">نوع الإجازة</label><select id="leave_type" v-model="workflow.leave_type_id" class="field"><option value="">كل الأنواع</option><option v-for="type in leaveTypes" :key="type.id" :value="type.id">{{ type.name }}</option></select></div><div><label class="label" for="priority">الأولوية</label><input id="priority" v-model.number="workflow.priority" type="number" class="field"></div><div><label class="label" for="effective">تاريخ السريان</label><input id="effective" v-model="workflow.effective_from" type="date" class="field"></div></div><div class="border-t border-slate-100 pt-3"><h3 class="mb-2 font-semibold">خطوات الموافقة</h3><div v-for="(step,index) in workflow.steps" :key="index" class="mb-2 grid gap-2 sm:grid-cols-2"><select v-model="step.approver_role_id" class="field" :aria-label="`دور المعتمد في الخطوة ${index+1}`" required><option value="">اختر دورًا</option><option v-for="role in roles" :key="role.id" :value="role.id">{{ role.name }}</option></select><select v-model="step.approver_scope" class="field" :aria-label="`نطاق المعتمد في الخطوة ${index+1}`"><option value="department_manager">مدير القسم</option><option value="global">عام</option></select></div><button type="button" class="text-sm font-semibold text-teal-700 underline" @click="workflow.steps.push({approver_role_id:'',approver_scope:'global'})">إضافة خطوة</button></div><p v-if="Object.keys(workflow.errors).length" class="error">{{ Object.values(workflow.errors)[0] }}</p><button class="btn-primary" :disabled="workflow.processing">إنشاء المسار</button></form><div class="mt-6 border-t border-slate-100 pt-4"><h3 class="mb-2 font-semibold">المسارات الحالية</h3><div v-for="w in workflows" :key="w.id" class="flex justify-between py-2 text-sm"><span>{{ w.name }}</span><span class="text-slate-500">{{ w.steps?.length }} خطوات</span></div></div></section>
        <section class="panel p-5"><h2 class="text-lg font-bold text-[#1F3A5F]">بدل أو استقطاع دوري</h2><form class="mt-4 grid gap-3 sm:grid-cols-2" @submit.prevent="saveComponent"><div><label class="label" for="component_employee">الموظف</label><select id="component_employee" v-model="componentEmployee.employee_id" class="field" required><option value="">اختر موظفًا</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.first_name }} {{ e.last_name }}</option></select></div><div><label class="label" for="component_kind">النوع</label><select id="component_kind" v-model="component.kind" class="field"><option value="allowance">بدل</option><option value="deduction">استقطاع</option></select></div><div><label class="label" for="component_code">الرمز</label><input id="component_code" v-model.trim="component.code" class="field" required></div><div><label class="label" for="component_label">الوصف</label><input id="component_label" v-model.trim="component.label" class="field" required></div><div><label class="label" for="component_amount">المبلغ</label><input id="component_amount" v-model.number="component.amount" type="number" step="0.01" min="0" class="field" required></div><div><label class="label" for="component_from">تاريخ السريان</label><input id="component_from" v-model="component.effective_from" type="date" class="field" required></div><div class="sm:col-span-2"><button class="btn-primary" :disabled="component.processing">إضافة البند</button></div><p v-if="Object.keys(component.errors).length" class="error sm:col-span-2">{{ Object.values(component.errors)[0] }}</p></form></section>
    </div>
</HrmsLayout></template>
